SELECT notification_id, receiver_id, type, message, target_url, read_at, created_at FROM notification WHERE receiver_id = #{receiverId}
AND notification_id < #{lastNotificationId}
ORDER BY notification_id DESC LIMIT #{size}

SELECT EXISTS (
SELECT 1
FROM notification
WHERE notification_id = #{notificationId}
AND receiver_id = #{receiverId}
)

mapper.update:
UPDATE notification
SET read_at = NOW()
WHERE notification_id = #{notificationId}
AND receiver_id = #{receiverId}
AND read_at IS NULL
